reproduction.script:
// Disposable metabolic kernels only. No database, network, stepWorld or live state.
// Run from the repository root:
// timeout --signal=TERM --kill-after=5s 120s node --max-old-space-size=384 --import tsx output/research/infant-food-access-2026-10-09.mjs
import fs from "node:fs";
import path from "node:path";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";

const started = performance.now();
const root = path.resolve(import.meta.dirname, "../..");
const output = path.join(import.meta.dirname, "infant-food-access-2026-10-09.json");
const sha = (value) => createHash("sha256").update(value).digest("hex");
function sourceFiles(directory = "src/simulation") {
  return fs.readdirSync(path.join(root, directory), { withFileTypes: true })
    .flatMap((entry) => entry.isDirectory()
      ? sourceFiles(directory + "/" + entry.name)
      : entry.name.endsWith(".ts") ? [directory + "/" + entry.name] : [])
    .sort();
}
function fingerprint() {
  const files = sourceFiles().map((relative) => ({
    path: relative,
    sha256: sha(fs.readFileSync(path.join(root, relative))),
  }));
  return { files, aggregateSHA256: sha(JSON.stringify(files)),
    method: "SHA-256 of JSON.stringify(sorted [{path,sha256(raw file bytes)}])" };
}
const sourceBefore = fingerprint();
const script = fs.readFileSync(import.meta.filename, "utf8");
const report = {
  recordedAtUTC: new Date().toISOString(),
  status: "running",
  computeBudgetSeconds: 120,
  evidenceKind: "Actual physiology/subsistence kernels on new disposable fixtures; no full-world advancement",
  source: sourceBefore,
  runtime: { node: process.version, platform: process.platform, arch: process.arch,
    packageLockSHA256: sha(fs.readFileSync(path.join(root, "package-lock.json"))) },
  reproduction: { path: "output/research/infant-food-access-2026-10-09.mjs",
    command: "timeout --signal=TERM --kill-after=5s 120s node --max-old-space-size=384 --import tsx output/research/infant-food-access-2026-10-09.mjs",
    scriptSHA256: sha(script), script },
  holderCases: [], growthCases: [], checks: {},
};
function save() {
  report.elapsedWallMs = performance.now() - started;
  fs.writeFileSync(output, JSON.stringify(report, null, 2) + "\n");
}
function budget() {
  if (performance.now() - started > 110000)
    throw new Error("Internal 110-second stop reached; outer compute limit is 120 seconds.");
}
function close(a, b, tolerance = 1e-10, label = "quantity") {
  assert.ok(Number.isFinite(a) && Number.isFinite(b) && Math.abs(a - b) <= tolerance,
    label + ": " + a + " versus " + b + ", tolerance " + tolerance);
}
save();

try {
  const [worldAPI, physiology, subsistence, laws, chemistry, content, thermo, types, settlement, planet] = await Promise.all([
    import("../../src/simulation/world.ts"),
    import("../../src/simulation/physiology.ts"),
    import("../../src/simulation/subsistence.ts"),
    import("../../src/simulation/laws.ts"),
    import("../../src/simulation/chemistry.ts"),
    import("../../src/simulation/content.ts"),
    import("../../src/simulation/thermodynamics.ts"),
    import("../../src/simulation/types.ts"),
    import("../../src/simulation/settlement.ts"),
    import("../../src/simulation/planet.ts"),
  ]);
  assert.deepEqual(fingerprint(), sourceBefore, "Simulation source changed during imports.");
  const { createWorld, getTile } = worldAPI;
  const { prepareMetabolism, feedMetabolicNeeds, finishMetabolism, refillMetabolicIntake,
    initialMetabolism, bodyHeatBalance, intakeCapacity, PHYSIOLOGY, METABOLISM } = physiology;
  const { feedIntake } = subsistence;
  const { ledger, emptyStock, LAWS } = laws;
  const { elementLedger, CHEMISTRY } = chemistry;
  const { MATERIALS } = content;
  const { heatCapacity } = thermo;
  const { PLANET } = planet;
  const DT = types.HOURS_PER_TICK;
  const FOOD_KJ = LAWS.chemicalEnergy * MATERIALS.biomass.carbon;
  assert.equal(DT, 0.25);

  const template = createWorld(1847, 64, 64, "planet-1", 2);
  const civ = template.civilizations[0];
  const originalPeople = template.citizens.filter((person) => person.civId === civ.id).slice(0, 2);
  assert.equal(originalPeople.length, 2);
  template.civilizations = [civ];
  template.citizens = originalPeople;
  template.animals = [];
  template.structures = [];
  template.caravans = [];
  template.events = [];
  template.pendingEvents = [];
  template.tick = 960;
  civ.x = 4; civ.y = 4;
  civ.stock = emptyStock();
  civ.relations = {};
  for (const tile of template.tiles) {
    tile.terrain = "meadow";
    tile.owner = null;
    tile.temperature = 33;
    tile.water = 1000;
    tile.ice = 0;
    tile.air.snow = 0;
  }
  originalPeople.forEach((person, index) => {
    person.id = index === 0 ? "diagnostic-infant" : "diagnostic-adult";
    person.civId = civ.id;
    person.x = civ.x; person.y = civ.y;
    person.age = index === 0 ? 0 : 30;
    person.body = index === 0 ? 2 : 18;
    person.metabolism = initialMetabolism(person.body);
    person.provisions = 0;
    person.wrapMass = 0;
    person.cargo = null;
    person.health = 100;
    person.hunger = 0;
    person.hydration = index === 0 ? 1.5 : 8;
    person.sick = 0;
    person.journeyId = null;
    person.task = null;
    person.pregnancy = null;
    person.partnerId = null;
    person.parentIds = [];
  });

  function personState(person) {
    return { id: person.id, ageYears: person.age, bodyKg: person.body,
      structuralKg: person.body - person.metabolism.reserves,
      reserveSubsetKg: person.metabolism.reserves, intakeKg: person.metabolism.intake,
      provisionsKg: person.provisions, cargoBiomassKg: person.cargo?.material === "biomass" ? person.cargo.amount : 0,
      hydrationKg: person.hydration, satiety: person.hunger, health: person.health,
      x: person.x, y: person.y };
  }
  function states(world) { return world.citizens.map(personState); }
  function pools(world) {
    const total = ledger(world);
    return { elements: elementLedger(world), chemicalKJ: total.chemical,
      releasedKJ: world.energy.released, capturedKJ: world.energy.captured,
      oxygenKg: world.atmosphere.oxygen,
      humanBiomassKg: world.citizens.reduce((sum, p) => sum + p.body + p.metabolism.intake + p.provisions +
        (p.cargo?.material === "biomass" ? p.cargo.amount : 0), 0) +
        world.civilizations.reduce((sum, c) => sum + c.stock.biomass, 0) };
  }
  function conservation(before, world, oxidationKg) {
    const after = pools(world);
    const elementResidualsKg = Object.fromEntries([...new Set([...Object.keys(before.elements), ...Object.keys(after.elements)])]
      .map((symbol) => [symbol, (after.elements[symbol] ?? 0) - (before.elements[symbol] ?? 0)]));
    const maximumElementResidualKg = Math.max(...Object.values(elementResidualsKg).map(Math.abs));
    const chemicalPlusReleasedResidualKJ = after.chemicalKJ - before.chemicalKJ +
      after.releasedKJ - before.releasedKJ - after.capturedKJ + before.capturedKJ;
    const humanBiomassResidualKg = after.humanBiomassKg - before.humanBiomassKg + oxidationKg;
    const oxygenResidualKg = before.oxygenKg - after.oxygenKg - oxidationKg * MATERIALS.biomass.carbon * CHEMISTRY.oxygenPerOrganic;
    const releasedResidualKJ = after.releasedKJ - before.releasedKJ - oxidationKg * FOOD_KJ;
    close(maximumElementResidualKg, 0, 5e-6, "Whole-fixture elements");
    close(chemicalPlusReleasedResidualKJ, 0, 1e-3, "Chemical inventory plus released energy");
    close(humanBiomassResidualKg, 0, 1e-10, "Direct human biomass account");
    close(oxygenResidualKg, 0, 5e-6, "Oxygen stoichiometry");
    close(releasedResidualKJ, 0, 1e-8, "Oxidized fuel versus released energy");
    return { passed: true, elementResidualsKg, maximumElementResidualKg,
      chemicalPlusReleasedResidualKJ, humanBiomassResidualKg, oxygenResidualKg,
      releasedResidualKJ, tolerances: { wholeElementKg: 5e-6, wholeChemicalKJ: 1e-3,
        directHumanBiomassKg: 1e-10, oxygenKg: 5e-6, releasedKJ: 1e-8 },
      reasonForWholeFixtureTolerance: "The generated inert environment retains large elemental/chemical reservoirs; direct compartment identities use the tighter mass tolerance." };
  }
  const fluxKeys = ["ingestedKg", "foodOxidizedKg", "reserveOxidizedKg", "reserveStoredKg", "structureStoredKg",
    "maintenanceKJ", "heatLossKJ", "releasedKJ", "meltKJ", "unmetMaintenanceKJ", "unmetColdKJ", "unremovedHeatKJ", "healthLoss"];
  function zeroFlux() { return Object.fromEntries(fluxKeys.map((key) => [key, 0])); }
  function intakeTransfers(before, after, phase) {
    return before.map((state, index) => {
      const next = after[index];
      const withdrawn = state.provisionsKg - next.provisionsKg + state.cargoBiomassKg - next.cargoBiomassKg;
      close(next.intakeKg - state.intakeKg, withdrawn, 1e-10, phase + " food to intake");
      return { phase, from: state.id + ".ownOutsideBodyFood", to: state.id + ".intake", amountKg: withdrawn };
    });
  }
  function interval(world, reverse = false) {
    world.tick++;
    for (const person of world.citizens) person.age += DT / (24 * types.DAYS_PER_YEAR);
    const before = states(world);
    const order = reverse ? [...world.citizens].reverse() : world.citizens;
    const tiles = [...new Set(world.citizens.map((p) => getTile(world, p.x, p.y)))];
    const thermalBefore = tiles.map((tile) => ({ tile, temperature: tile.temperature,
      capacity: heatCapacity(tile), vapor: tile.air.vapor }));
    const steps = order.map((person) => prepareMetabolism(world, person, getTile(world, person.x, person.y), DT, false, 0));
    feedMetabolicNeeds(world, steps);
    const afterCurrent = states(world);
    const transfers = intakeTransfers(before, afterCurrent, "currentDemand");
    for (const step of steps) finishMetabolism(world, step);
    const afterOxidation = states(world);
    refillMetabolicIntake(world, steps);
    const after = states(world);
    transfers.push(...intakeTransfers(afterOxidation, after, "optionalBuffer"));
    const flux = world.citizens.map((person) => ({ id: person.id, ...person.metabolism.last }));
    let maximumCompartmentResidualKg = 0;
    for (let index = 0; index < before.length; index++) {
      const a = before[index], b = after[index], f = flux[index];
      const residuals = [
        b.intakeKg - a.intakeKg - f.ingestedKg + f.foodOxidizedKg + f.reserveStoredKg + f.structureStoredKg,
        b.bodyKg - a.bodyKg + f.reserveOxidizedKg - f.reserveStoredKg - f.structureStoredKg,
        b.reserveSubsetKg - a.reserveSubsetKg + f.reserveOxidizedKg - f.reserveStoredKg,
        b.structuralKg - a.structuralKg - f.structureStoredKg,
      ];
      for (const value of residuals) close(value, 0, 1e-10, "Per-interval compartment identity");
      maximumCompartmentResidualKg = Math.max(maximumCompartmentResidualKg, ...residuals.map(Math.abs));
      assert.ok(b.reserveSubsetKg >= 0 && b.reserveSubsetKg <= b.bodyKg);
      assert.ok(b.intakeKg >= 0 && b.provisionsKg >= 0);
      close(f.unmetMaintenanceKJ, 0, 1e-8, "Maintenance fully funded");
      close(f.unmetColdKJ, 0, 1e-8, "No cold shortfall in funded controls");
      close(f.unremovedHeatKJ, 0, 1e-8, "No heat removal shortfall");
      close(f.meltKJ, 0, 1e-10, "No ice melting");
      assert.ok(b.hydrationKg > 0.8 * physiology.hydrationTarget(world.citizens[index]));
    }
    const sensibleKJ = thermalBefore.reduce((sum, value) => sum +
      value.capacity * (value.tile.temperature - value.temperature), 0);
    const sweatVaporKg = thermalBefore.reduce((sum, value) => sum + value.tile.air.vapor - value.vapor, 0);
    const releasedKJ = flux.reduce((sum, f) => sum + f.releasedKJ, 0);
    const thermalResidualKJ = sensibleKJ + sweatVaporKg * PLANET.vaporizationHeat - releasedKJ;
    close(thermalResidualKJ, 0, 1e-6, "Sensible heat plus actual evaporation");
    return { tick: world.tick, simulatedHours: DT, transfers, flux, after,
      environmental: { temperaturesBeforeC: thermalBefore.map((value) => value.temperature),
        sensibleKJ, sweatVaporKg, thermalResidualKJ }, maximumCompartmentResidualKg };
  }
  function runHolder(holder, reverse) {
    budget();
    const world = structuredClone(template), [infant, adult] = world.citizens;
    const community = world.civilizations[0];
    community.stock.biomass = 3 + intakeCapacity(adult);
    const priorAllocation = pools(world);
    const adultPreload = intakeCapacity(adult);
    close(feedIntake(world, [{ person: adult, amount: adultPreload }]).get(adult), adultPreload);
    const outsideFood = community.stock.biomass;
    const recipient = holder === "infant" ? infant : adult;
    community.stock.biomass -= outsideFood;
    recipient.provisions += outsideFood;
    infant.x = 32; infant.y = 32;
    adult.x = holder === "distantAdult" ? 52 : 32; adult.y = 32;
    close(outsideFood, 3);
    for (const person of world.citizens) assert.equal(settlement.canReachCampStocks(world, community, person), false);
    conservation(priorAllocation, world, 0);
    const initial = states(world), before = pools(world), rng = world.rng;
    const totals = Object.fromEntries(world.citizens.map((p) => [p.id, zeroFlux()]));
    const trace = [];
    for (let step = 0; step < 16; step++) {
      budget();
      const row = interval(world, reverse);
      for (const flux of row.flux)
        for (const key of fluxKeys) totals[flux.id][key] += flux[key];
      trace.push(row);
    }
    const oxidationKg = Object.values(totals).reduce((sum, total) => sum + total.foodOxidizedKg + total.reserveOxidizedKg, 0);
    assert.equal(world.rng, rng, "Kernel diagnostic must consume no RNG.");
    assert.equal(adult.provisions, holder === "infant" ? 0 : outsideFood,
      "Adult preload must prevent eating/refilling from the comparison pool.");
    close(totals[adult.id].ingestedKg, 0);
    close(totals[adult.id].reserveOxidizedKg, 0);
    assert.equal(community.stock.biomass, 0);
    return { holder, order: reverse ? "adult-first" : "infant-first", simulatedHours: 4,
      initialOutsideFoodKg: outsideFood, adultIntakePreloadKg: adultPreload,
      inputAllocation: "Initial controlled distribution from a 3.9 kg fixture pool; not an implemented peer-care action.",
      initial, final: states(world), totals, trace,
      conservation: conservation(before, world, oxidationKg), rngUnchanged: world.rng === rng,
      maximumTemperatureDriftFrom33C: Math.max(...trace.flatMap((row) => row.environmental.temperaturesBeforeC.map((t) => Math.abs(t - 33)))) };
  }
  report.protocol = {
    worldVersion: template.version, lawsVersion: template.lawsVersion,
    seed: 1847, representedTiles: template.tiles.length,
    actualFunctions: ["feedIntake", "prepareMetabolism", "feedMetabolicNeeds", "finishMetabolism", "refillMetabolicIntake", "ledger", "elementLedger", "canReachCampStocks"],
    stepHours: DT, holderDurationHours: 4, holderStepsPerCase: 16,
    fixedInput: { looseFoodKg: 3, adultPreloadedIntakeKg: 0.9,
      infantBodyKg: 2, infantReserveSubsetKg: 0.2, infantInitialHydrationKg: 1.5,
      adultBodyKg: 18, adultReserveSubsetKg: 1.8, adultInitialHydrationKg: 8,
      holderAmbientTemperatureC: 33, active: false, shelterResistance: 0, wrapKg: 0 },
    metabolicParametersUnchanged: METABOLISM,
    excludedProcesses: ["stepWorld", "birth/gestation", "cognition and decisions", "movement or care work", "packing", "routine nonthermal water loss", "weather/ecology", "inventory spoilage", "health recovery and nonmetabolic injury"],
    environmentalControl: "Initial homogeneous 33 C, liquid water and ample finite atmospheric oxygen. Actual sweating/respiration are retained; no water, food, oxygen or temperature reset occurs during a case.",
    interpretation: "Four hours of kernel integration, not a four-hour full-world forecast or proof of survival. The infant is initially hydrated for isolation, not asserted to be a just-born anatomical human.",
  };
  for (const holder of ["infant", "nearbyAdult", "distantAdult"])
    for (const reverse of [false, true]) {
      report.holderCases.push(runHolder(holder, reverse));
      save();
    }
  const byHolder = (holder) => report.holderCases.find((entry) => entry.holder === holder && entry.order === "infant-first");
  const own = byHolder("infant"), nearby = byHolder("nearbyAdult"), distant = byHolder("distantAdult");
  assert.ok(own.totals["diagnostic-infant"].ingestedKg > 0);
  close(own.totals["diagnostic-infant"].reserveOxidizedKg, 0);
  for (const entry of [nearby, distant]) {
    close(entry.totals["diagnostic-infant"].ingestedKg, 0);
    assert.ok(entry.totals["diagnostic-infant"].reserveOxidizedKg > 0);
    close(entry.totals["diagnostic-infant"].structureStoredKg, 0);
  }
  assert.deepEqual(nearby.totals, distant.totals);
  const orderControls = [];
  for (const holder of ["infant", "nearbyAdult", "distantAdult"]) {
    const a = report.holderCases.find((entry) => entry.holder === holder && entry.order === "infant-first");
    const b = report.holderCases.find((entry) => entry.holder === holder && entry.order === "adult-first");
    assert.deepEqual(a.totals, b.totals);
    assert.deepEqual(a.final, b.final);
    orderControls.push({ holder, exactFinalStatesAndMetabolicTotalsEqual: true });
  }
  report.checks.holder = { ownFoodFeedsInfant: true, noImplementedPeerTransfer: true,
    nearbyAndDistantAdultMetabolicTotalsExactlyEqual: true, adultComparisonFoodUntouched: true, orderControls };

  function runGrowth(heatMultiple, ageYears = 0) {
    budget();
    const world = structuredClone(template), infant = world.citizens[0];
    world.citizens = [infant];
    infant.age = ageYears;
    const community = world.civilizations[0];
    community.stock.biomass = intakeCapacity(infant);
    const initialAllocation = pools(world);
    const amount = community.stock.biomass;
    close(feedIntake(world, [{ person: infant, amount }]).get(infant), amount);
    infant.x = 32; infant.y = 32;
    assert.equal(settlement.canReachCampStocks(world, community, infant), false);
    const balance = bodyHeatBalance(infant, 0, false, 0);
    const tile = getTile(world, infant.x, infant.y);
    tile.temperature = PHYSIOLOGY.skinTemperature - heatMultiple * balance.metabolicDemandW * PHYSIOLOGY.airResistance / balance.area;
    conservation(initialAllocation, world, 0);
    const initial = personState(infant), before = pools(world), rng = world.rng;
    const trace = interval(world);
    const flux = trace.flux[0];
    close(flux.heatLossKJ, flux.maintenanceKJ * heatMultiple, 1e-8);
    close(flux.reserveOxidizedKg, 0);
    close(flux.reserveStoredKg, 0);
    assert.ok(flux.structureStoredKg > 0);
    assert.equal(world.rng, rng);
    return { heatMultiple, initialAgeYears: ageYears, initialTemperatureC: trace.environmental.temperaturesBeforeC[0],
      initial, final: personState(infant), flux, trace,
      conservation: conservation(before, world, flux.foodOxidizedKg + flux.reserveOxidizedKg), rngUnchanged: true };
  }
  for (const [multiple, age] of [[1, 0], [2, 0], [1, 1]]) {
    report.growthCases.push(runGrowth(multiple, age));
    save();
  }
  const [maintenance, cold, older] = report.growthCases;
  const retentionRatio = cold.flux.structureStoredKg / maintenance.flux.structureStoredKg;
  close(retentionRatio, 2, 1e-10, "Additional heat oxidation doubles the present retention allowance");
  for (const key of fluxKeys) close(maintenance.flux[key], older.flux[key], 1e-10, "Age-only flux control: " + key);
  report.checks.growth = { additionalHeatRetentionRatio: retentionRatio,
    ageZeroVersusOneSameBodyFluxesEqualWithinTolerance: true,
    interpretation: "Source-proven conserved coupling to oxidation and absence of age dependence in this matched-body kernel; not a calibrated biological growth law." };
  report.sourceAfter = fingerprint();
  assert.deepEqual(report.sourceAfter, sourceBefore, "Source changed during diagnostic.");
  report.checks.sourceUnchangedDuringRun = true;
  report.status = "passed";
  report.peakRSSBytes = process.resourceUsage().maxRSS * 1024;
  save();
  console.log(JSON.stringify({ status: report.status, output, elapsedWallMs: report.elapsedWallMs,
    sourceSHA256: sourceBefore.aggregateSHA256, holderCases: report.holderCases.length,
    growthCases: report.growthCases.length, retentionRatio }));
} catch (error) {
  report.status = "failed_or_inconclusive";
  report.failure = { name: error.name, message: error.message, stack: error.stack };
  report.sourceAfter = fingerprint();
  save();
  console.error(JSON.stringify({ status: report.status, output, failure: report.failure.message, elapsedWallMs: report.elapsedWallMs }));
  process.exitCode = 1;
}
